import { Component, TemplateRef, computed, input, model, output } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';

type Row = Record<string, unknown>;
const DAY = 86400000;
const toDate = (v: unknown): Date | null => {
  if (v instanceof Date) return v;
  if (v == null || v === '') return null;
  const d = new Date(String(v));
  return isNaN(d.getTime()) ? null : d;
};
const floorDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());
const daysBetween = (a: Date, b: Date) => Math.round((floorDay(b).getTime() - floorDay(a).getTime()) / DAY);
const sameDay = (a: Date, b: Date) => floorDay(a).getTime() === floorDay(b).getTime();

/** hrm-gantt — sơ đồ Gantt (prototype): cột nhãn trái (tên · hạn) GHIM + timeline bên phải với
 *  dải THÁNG trên dải NGÀY, mỗi bản ghi = 1 thanh start→end + % tiến độ, nhãn task cạnh thanh.
 *  Header ghim trên, cột trái ghim trái → cuộn ngang/dọc vẫn đọc được. Vạch "hôm nay".
 *  KHÔNG dependency/kéo resize. Ngày nhận Date hoặc chuỗi ISO. Toàn token → tự Light/Dark.
 *
 *  <hrm-gantt [data]="rows" startField="start" endField="end" labelField="name"
 *     progressField="progress" [dayWidth]="36" labelHeader="Tên" dateHeader="Hạn"
 *     (barClick)="open($event)" /> */
@Component({
  selector: 'hrm-gantt',
  imports: [NgTemplateOutlet],
  template: `
    <div class="gt" [style.--gt-dw]="dayWidth() + 'px'">
      <div class="gt-in">
        <!-- Cột nhãn trái (ghim trái) -->
        <div class="gt-labels" [style.width.px]="labelWidth()">
          <div class="gt-lh">
            <span class="gt-lh-t">{{ labelHeader() }}</span>
            <span class="gt-lh-d">{{ dateHeader() }}</span>
          </div>
          @for (b of bars(); track b.id) {
            <div class="gt-lrow" [class.is-sel]="isSel(b.row)" (click)="barClick.emit(b.row)" [attr.title]="b.label">
              @if (selectable()) {
                <label class="gt-check" (click)="$event.stopPropagation()">
                  <input type="checkbox" [checked]="isSel(b.row)"
                    (change)="toggleSel(b.row, $any($event.target).checked)" />
                </label>
              }
              <span class="gt-lrow-main">
                @if (labelTemplate()) {
                  <ng-container [ngTemplateOutlet]="labelTemplate()!" [ngTemplateOutletContext]="{ $implicit: b.row }" />
                } @else {
                  <span class="gt-lrow-t">{{ b.label }}</span>
                }
              </span>
              <span class="gt-lrow-d" [class.is-late]="b.late">{{ b.endText }}</span>
            </div>
          }
        </div>

        <!-- Timeline -->
        <div class="gt-track" [style.width.px]="days().length * dayWidth()">
          <!-- Header: dải tháng + dải ngày (ghim trên) -->
          <div class="gt-head">
            <div class="gt-months">
              @for (m of months(); track m.key) {
                <div class="gt-month" [style.width.px]="m.count * dayWidth()">{{ m.label }}</div>
              }
            </div>
            <div class="gt-days">
              @for (d of days(); track d.t) {
                <div class="gt-day" [class.is-weekend]="d.weekend" [class.is-today]="d.today"
                  [style.width.px]="dayWidth()">{{ d.day }}</div>
              }
            </div>
          </div>

          <!-- Thân: gridline ngày + thanh -->
          <div class="gt-body">
            @if (todayLeft() !== null) { <div class="gt-today" [style.left.px]="todayLeft()"></div> }
            @for (b of bars(); track b.id) {
              <div class="gt-row">
                @if (b.width > 0) {
                  <div class="gt-bar" [style.left.px]="b.left" [style.width.px]="b.width"
                    [attr.data-tone]="b.tone || null"
                    (click)="barClick.emit(b.row)" [attr.title]="b.label + ' · ' + b.progress + '%'">
                    <div class="gt-fill" [style.width.%]="b.progress"></div>
                    @if (b.progress > 0) { <span class="gt-bar-p">{{ b.progress }}%</span> }
                  </div>
                  <!-- Nhãn task cạnh thanh (như ClickUp) -->
                  <span class="gt-bar-l" [style.left.px]="b.left + b.width + 8">{{ b.label }}</span>
                }
              </div>
            }
          </div>
        </div>
      </div>
    </div>
  `,
  host: { class: 'hrm-gantt' },
  styles: [`
    /* Lấp đầy vùng chứa; 1 vùng cuộn duy nhất (ngang + dọc) — cột trái ghim trái, header ghim trên. */
    :host { display: block; height: 100%; min-height: 0; }
    .gt {
      height: 100%; overflow: auto;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
    }
    .gt-in { display: flex; width: max-content; min-width: 100%; }

    /* ── Cột nhãn trái ─────────────────────────────────────────── */
    .gt-labels {
      flex: none; position: sticky; left: 0; z-index: 3;
      background: var(--bg-surface); border-right: 1px solid var(--border-sub);
    }
    .gt-lh {
      position: sticky; top: 0; z-index: 4; height: 56px;
      display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 12px;
      background: var(--bg-surface-subtle); border-bottom: 1px solid var(--border-sub);
      font-size: var(--fs-12); font-weight: 600; color: var(--text-sub);
    }
    .gt-lrow {
      height: 40px; display: flex; align-items: center; justify-content: space-between; gap: 8px;
      padding: 0 12px; border-bottom: 1px solid var(--border-soft); cursor: pointer;
      transition: background var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .gt-lrow:hover { background: var(--bg-surface-subtle); }
    .gt-lrow.is-sel { background: var(--primary-bg-subtle); }
    /* Checkbox chọn — đầu hàng nhãn. */
    .gt-check { display: grid; place-items: center; flex: none; margin-right: 8px; cursor: pointer; }
    .gt-check input { width: 14px; height: 14px; margin: 0; cursor: pointer; accent-color: var(--primary-base); }
    .gt-lrow-main { flex: 1; min-width: 0; display: flex; align-items: center; overflow: hidden; }
    .gt-lrow-t { font-size: var(--fs-14); color: var(--text-body); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .gt-lrow-d { flex: none; font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .gt-lrow-d.is-late { color: var(--error-base); font-weight: 600; }

    /* ── Timeline ──────────────────────────────────────────────── */
    .gt-track { position: relative; flex: none; }

    .gt-head { position: sticky; top: 0; z-index: 2; background: var(--bg-surface-subtle); border-bottom: 1px solid var(--border-sub); }
    .gt-months { display: flex; height: 28px; }
    .gt-month {
      flex: none; display: flex; align-items: center; padding: 0 10px;
      font-size: var(--fs-12); font-weight: 600; color: var(--text-strong);
      border-right: 1px solid var(--border-sub); white-space: nowrap; overflow: hidden;
    }
    .gt-days { display: flex; height: 28px; }
    .gt-day {
      flex: none; display: flex; align-items: center; justify-content: center;
      font-size: var(--fs-11); color: var(--text-sub); border-right: 1px solid var(--border-soft);
      font-variant-numeric: tabular-nums;
    }
    .gt-day.is-weekend { color: var(--text-soft); background: var(--bg-surface-muted, var(--bg-surface-subtle)); }
    .gt-day.is-today { color: var(--primary-base); font-weight: 700; }

    /* Gridline ngày chạy dọc thân (nhẹ) — giúp dò mốc thời gian. */
    .gt-body {
      position: relative;
      background-image: repeating-linear-gradient(to right,
        var(--border-soft) 0 1px, transparent 1px var(--gt-dw, 36px));
    }
    .gt-row {
      height: 40px; border-bottom: 1px solid var(--border-soft); position: relative;
      transition: background var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .gt-row:hover { background: color-mix(in srgb, var(--bg-surface-subtle) 70%, transparent); }

    .gt-bar {
      position: absolute; top: 8px; height: 24px; border-radius: var(--radius-md);
      background: var(--primary-bg-subtle); border: 1px solid var(--primary-border);
      overflow: hidden; cursor: pointer; display: flex; align-items: center;
      transition: box-shadow var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .gt-bar:hover { box-shadow: var(--shadow-regular-sm); border-color: var(--primary-base); }
    .gt-fill { position: absolute; inset: 0 auto 0 0; background: var(--primary-base); opacity: .9; }
    .gt-bar-p { position: relative; z-index: 1; font-size: var(--fs-11); font-weight: 600; color: var(--static-white, #fff); padding-left: 8px; }
    /* Nhãn task đặt cạnh thanh — không chắn chuột. */
    .gt-bar-l {
      position: absolute; top: 8px; height: 24px; display: flex; align-items: center;
      font-size: var(--fs-13); color: var(--text-body); white-space: nowrap; pointer-events: none;
    }

    /* Tông màu thanh theo giai đoạn (barTone) — mặc định primary. */
    .gt-bar[data-tone='success'] { border-color: var(--success-base); }
    .gt-bar[data-tone='success'] .gt-fill { background: var(--success-base); }
    .gt-bar[data-tone='info'] { border-color: var(--info-base); }
    .gt-bar[data-tone='info'] .gt-fill { background: var(--info-base); }
    .gt-bar[data-tone='warning'] { border-color: var(--warning-base); }
    .gt-bar[data-tone='warning'] .gt-fill { background: var(--warning-base); }
    .gt-bar[data-tone='error'] { border-color: var(--error-base); }
    .gt-bar[data-tone='error'] .gt-fill { background: var(--error-base); }
    .gt-bar[data-tone='neutral'] { border-color: var(--border-sub); }
    .gt-bar[data-tone='neutral'] .gt-fill { background: var(--neutral-400); }

    .gt-today { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--error-base); z-index: 2; }
  `],
})
export class HrmGantt {
  readonly data = input<Row[]>([]);
  readonly startField = input('start');
  readonly endField = input('end');
  readonly labelField = input('name');
  /** Field % tiến độ (0–100). Bỏ trống → 0. */
  readonly progressField = input('');
  readonly rowKey = input('id');
  readonly dayWidth = input(36);
  readonly labelWidth = input(240);
  /** Nhãn cột tên (i18n, bên gọi cấp). */
  readonly labelHeader = input('');
  /** Nhãn cột hạn (i18n). */
  readonly dateHeader = input('');
  /** Template render ô nhãn trái (avatar/chấm trạng thái/chức vụ…); context $implicit = row.
   *  Bỏ trống → chỉ hiện labelField. Cột hạn bên phải luôn giữ. */
  readonly labelTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  /** Hàm suy TÔNG MÀU thanh theo bản ghi ('success' | 'info' | 'warning' | 'error' | 'neutral').
   *  Bỏ trống → thanh dùng màu primary. VD: (r) => r.stage === 'done' ? 'success' : 'info'. */
  readonly barTone = input<((row: Row) => string) | null>(null);
  /** Cho chọn nhiều bản ghi (checkbox ở cột nhãn trái). */
  readonly selectable = input(false);
  /** Khoá các bản ghi đang chọn (two-way). */
  readonly selectedKeys = model<unknown[]>([]);
  /** Click nhãn hoặc thanh → mở chi tiết. */
  readonly barClick = output<Row>();

  protected isSel(row: Row): boolean { return this.selectedKeys().includes(row[this.rowKey()]); }
  protected toggleSel(row: Row, checked: boolean): void {
    const k = row[this.rowKey()];
    const cur = this.selectedKeys();
    this.selectedKeys.set(checked ? [...cur, k] : cur.filter((x) => x !== k));
  }

  /** dd/MM — cố định, không theo locale trình duyệt (tránh en-US đảo thành MM/dd). */
  private fmtDate(d: Date): string {
    return `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`;
  }

  /** Khoảng ngày bao trọn mọi task (đệm 1 ngày mỗi đầu). */
  private readonly range = computed(() => {
    const ds: Date[] = [];
    for (const r of this.data()) {
      const s = toDate(r[this.startField()]), e = toDate(r[this.endField()]);
      if (s) ds.push(s); if (e) ds.push(e);
    }
    if (!ds.length) return null;
    let min = ds[0], max = ds[0];
    for (const d of ds) { if (d < min) min = d; if (d > max) max = d; }
    const start = floorDay(new Date(min.getTime() - DAY));
    const end = floorDay(new Date(max.getTime() + DAY));
    return { start, days: daysBetween(start, end) + 1 };
  });

  protected readonly days = computed(() => {
    const r = this.range();
    if (!r) return [];
    const now = new Date();
    const out: { t: number; day: number; weekend: boolean; today: boolean }[] = [];
    for (let i = 0; i < r.days; i++) {
      const d = new Date(r.start.getTime() + i * DAY);
      const wd = d.getDay();
      out.push({ t: d.getTime(), day: d.getDate(), weekend: wd === 0 || wd === 6, today: sameDay(d, now) });
    }
    return out;
  });

  /** Dải tháng: gộp các ngày cùng tháng thành 1 ô (rộng = số ngày × dayWidth). */
  protected readonly months = computed(() => {
    const r = this.range();
    if (!r) return [];
    const out: { key: string; label: string; count: number }[] = [];
    for (let i = 0; i < r.days; i++) {
      const d = new Date(r.start.getTime() + i * DAY);
      const key = `${d.getFullYear()}-${d.getMonth()}`;
      const last = out[out.length - 1];
      if (last && last.key === key) last.count++;
      else out.push({ key, label: `Tháng ${d.getMonth() + 1}, ${d.getFullYear()}`, count: 1 });
    }
    return out;
  });

  protected readonly bars = computed(() => {
    const r = this.range();
    if (!r) return [];
    const w = this.dayWidth(), sf = this.startField(), ef = this.endField();
    const lf = this.labelField(), pf = this.progressField(), rk = this.rowKey();
    const tone = this.barTone();
    const now = new Date();
    return this.data().map((row) => {
      const s = toDate(row[sf]), e = toDate(row[ef]);
      const left = s ? daysBetween(r.start, s) * w : 0;
      const dur = s && e ? daysBetween(s, e) + 1 : 0;
      const p = pf ? Number(row[pf]) || 0 : 0;
      const progress = Math.max(0, Math.min(100, p));
      return {
        id: row[rk], row, label: String(row[lf] ?? ''), left, width: dur * w, progress,
        tone: tone ? tone(row) : '',
        endText: e ? this.fmtDate(e) : '',
        /** Quá hạn = hết hạn trước hôm nay mà chưa xong. */
        late: !!e && e < floorDay(now) && progress < 100,
      };
    });
  });

  protected readonly todayLeft = computed(() => {
    const r = this.range();
    if (!r) return null;
    const off = daysBetween(r.start, new Date());
    return off >= 0 && off < r.days ? off * this.dayWidth() + this.dayWidth() / 2 : null;
  });
}
